import{_ as t,a as s}from"./chunks/project-import.BeRSVcDL.js";import{_ as n,o as e,c as o,a2 as i}from"./chunks/framework.Dx-TCpNt.js";const b=JSON.parse('{"title":"工程文件与格式","description":"KomaYomi 存储的一切都是普通文件：图片在 raw/，标注在 data/，生成结果在 exports/。本页介绍把这份工作搬到别处的三种方式，以及让旧文件保持可读、而不是变成考古现场的版本规则。","frontmatter":{"description":"KomaYomi 存储的一切都是普通文件：图片在 raw/，标注在 data/，生成结果在 exports/。本页介绍把这份工作搬到别处的三种方式，以及让旧文件保持可读、而不是变成考古现场的版本规则。"},"headers":[],"relativePath":"zh/guide/project-files.md","filePath":"zh/guide/project-files.md","lastUpdated":1794778371000}'),r={name:"zh/guide/project-files.md"};function d(l,a,p,c,h,g){return e(),o("div",null,[...a[0]||(a[0]=[i('<h1 id="工程文件与格式" tabindex="-1">工程文件与格式 <a class="header-anchor" href="#工程文件与格式" aria-label="Permalink to &quot;工程文件与格式&quot;">​</a></h1><p>KomaYomi 存储的一切都是普通文件：图片在 <code>raw/</code>，标注在 <code>data/</code>，生成结果在 <code>exports/</code>。本页介绍把这份工作搬到别处的三种方式，以及让旧文件保持可读、而不是变成考古现场的版本规则。</p><h2 id="它解决什么问题" tabindex="-1">它解决什么问题 <a class="header-anchor" href="#它解决什么问题" aria-label="Permalink to &quot;它解决什么问题&quot;">​</a></h2><p>标注是最昂贵的部分——数小时的分格修正、对齐和笔记。它们得扛住换机器、磁盘损坏、与学习伙伴共享，以及一次次版本升级。数据库备份是个黑盒；这里的格式就是普通 ZIP 和 JSON，拿常用工具就能打开检查。</p><h2 id="三个可移植层" tabindex="-1">三个可移植层 <a class="header-anchor" href="#三个可移植层" aria-label="Permalink to &quot;三个可移植层&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层</th><th>文件</th><th>内容</th><th>何时使用</th></tr></thead><tbody><tr><td><strong>工程包</strong></td><td><code>.mnproj</code></td><td>图片（打包模式）、页面 JSON、模板、预设、语言映射</td><td>换到另一台机器，或归档已完成的卷。</td></tr><tr><td><strong>交换文件</strong></td><td><code>.mntpl</code>、<code>.mnexp</code>、<code>.mnpage.json</code></td><td>一个版式、一种导出样式，或一页</td><td>分享可复用的版式或单个已标注页面。</td></tr><tr><td><strong>备份 ZIP</strong></td><td><code>.zip</code></td><td>整个 <code>data/</code> 文件夹</td><td>误操作后恢复，或保留定期安全副本。</td></tr></tbody></table><figure class="shot"><img src="'+t+`" alt="文件菜单：打开图库、工程文件、最近打开的卷、保存、导入与恢复"><figcaption>文件菜单把侧栏里的同类操作集中在一起：保存当前页、另存为工程、导入工程或页面，以及从备份恢复。</figcaption></figure><h2 id="工程包-mnproj" tabindex="-1">工程包（<code>.mnproj</code>） <a class="header-anchor" href="#工程包-mnproj" aria-label="Permalink to &quot;工程包（\`.mnproj\`）&quot;">​</a></h2><p><code>.mnproj</code> 是一个带文本清单的 ZIP：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>manifest.json</span></span>
<span class="line"><span>pages/&lt;volume&gt;/&lt;chapter&gt;/&lt;index&gt;.json</span></span>
<span class="line"><span>history/&lt;volume&gt;/&lt;chapter&gt;/&lt;index&gt;.json</span></span>
<span class="line"><span>templates/...</span></span>
<span class="line"><span>presets/...</span></span>
<span class="line"><span>config/library.json          (optional)</span></span>
<span class="line"><span>assets/&lt;sha1&gt;.&lt;ext&gt;          (packaged mode only)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p>页面版本历史会随工程一起迁移，重新打开后仍能看到<a href="/KomaYomi-docs/zh/guide/panels#页面历史">切格工作台</a>里描述的记录。</p><h3 id="引用模式与打包模式" tabindex="-1">引用模式与打包模式 <a class="header-anchor" href="#引用模式与打包模式" aria-label="Permalink to &quot;引用模式与打包模式&quot;">​</a></h3><table tabindex="0"><thead><tr><th>模式</th><th>图片</th><th>体积</th><th>可移植性</th></tr></thead><tbody><tr><td><strong>引用</strong></td><td>清单中只记录路径与 SHA-1 哈希。</td><td>小。</td><td>需要原始图片文件夹。支持按哈希或文件名补链。</td></tr><tr><td><strong>打包</strong></td><td>去重后存入 <code>assets/&lt;sha1&gt;.&lt;ext&gt;</code>。</td><td>大。</td><td>自包含；导入时把图片写入 <code>raw/</code>。</td></tr></tbody></table><h3 id="导出" tabindex="-1">导出 <a class="header-anchor" href="#导出" aria-label="Permalink to &quot;导出&quot;">​</a></h3><ol><li>打开侧栏的 <strong>工程文件…</strong>，或 <strong>文件 → 另存为工程…</strong>。</li><li>选择模式，填写工程名称和可选备注。</li><li>点击 <strong>生成并下载 .mnproj</strong>。</li></ol><p>清单记录应用版本、创建时间、语言映射、卷 / 话 / 页清单与图片哈希，以及笔记和标注数量。</p><h3 id="导入" tabindex="-1">导入 <a class="header-anchor" href="#导入" aria-label="Permalink to &quot;导入&quot;">​</a></h3><ol><li><strong>选择工程文件…</strong>。写入任何内容之前，对话框会先汇总卷、话、页、笔记、标注、图片和模板。</li><li>选择冲突策略：<strong>覆盖</strong>、<strong>合并</strong> 或 <strong>跳过</strong>。 <ul><li><strong>合并</strong> 在传入页面缺少分格和标注时保留现有内容，并按 id 合并笔记，不删除已有笔记。</li></ul></li><li>引用模式工程缺少图片时，可选一个存放原图的 <strong>补链目录</strong>。</li><li>点击 <strong>导入</strong>。</li></ol><p>安全行为：</p><ul><li>导入前会把当前 <code>data/</code> 快照到 <code>exports/</code>。</li><li>原工程文件备份到 <code>data/backups/projects/</code>。</li><li>导入后会列出缺失的图片；把它们放进补链目录，再用 <strong>合并</strong> 导入一次即可找回。</li></ul><h2 id="交换文件" tabindex="-1">交换文件 <a class="header-anchor" href="#交换文件" aria-label="Permalink to &quot;交换文件&quot;">​</a></h2><p><strong>交换文件…</strong> 负责三种小格式，不触碰整个图库。</p><h3 id="mntpl-——-版式模板" tabindex="-1"><code>.mntpl</code> —— 版式模板 <a class="header-anchor" href="#mntpl-——-版式模板" aria-label="Permalink to &quot;\`.mntpl\` —— 版式模板&quot;">​</a></h3><p>导出时会剥离卷 / 话 / 页绑定，因此模板可以导入另一部漫画，再重新绑定到当前卷、话或页。导入对话框可以绑定，并可选立即套用；已有页面会先保存。</p><h3 id="mnexp-——-导出模板" tabindex="-1"><code>.mnexp</code> —— 导出模板 <a class="header-anchor" href="#mnexp-——-导出模板" aria-label="Permalink to &quot;\`.mnexp\` —— 导出模板&quot;">​</a></h3><p>保存 HTML、Word 与打印文档的版式与样式设置。可以现在导出、以后导入。模板存储在 <code>data/templates/export.json</code>。</p><h3 id="mnpage-json-——-单页" tabindex="-1"><code>.mnpage.json</code> —— 单页 <a class="header-anchor" href="#mnpage-json-——-单页" aria-label="Permalink to &quot;\`.mnpage.json\` —— 单页&quot;">​</a></h3><p>可读的页面文档，包含分格、笔记、标签、分组、标注和对齐偏移。没有 schema 外壳的旧页面 JSON 也能导入，并会自动迁移。</p><ul><li><strong>导出当前页</strong> 写出当前页。</li><li><strong>选择页面 JSON…</strong> 然后 <strong>覆盖当前页</strong> 会替换所选页的分格、笔记和标注。</li><li>校验失败会报告确切的字段路径，绝不写入半成品数据。</li><li>原文件备份到 <code>data/backups/exchange/</code>。</li></ul><div class="warning custom-block"><p class="custom-block-title">未保存的改动</p><p>如果页面有未保存的编辑，交换导出不会包含它们，页面导入也可能覆盖它们。请先保存——对话框会警告，但很容易点过去。</p></div><h2 id="格式版本" tabindex="-1">格式版本 <a class="header-anchor" href="#格式版本" aria-label="Permalink to &quot;格式版本&quot;">​</a></h2><p>每种交换格式都带一个 schema 外壳：</p><div class="language-json vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;$schema&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://manga-memo.dev/schemas/page.schema.json&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;schemaVersion&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;appVersion&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;0.1.0&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;kind&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;page&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><table tabindex="0"><thead><tr><th>类型</th><th>文件</th><th>当前版本</th></tr></thead><tbody><tr><td><code>mnproj</code></td><td><code>.mnproj</code> 清单</td><td><strong>1</strong></td></tr><tr><td><code>mntpl</code></td><td>版式模板</td><td><strong>1</strong></td></tr><tr><td><code>mnexp</code></td><td>导出模板</td><td><strong>1</strong></td></tr><tr><td><code>page</code></td><td>页面文档</td><td><strong>1</strong></td></tr><tr><td><code>mntp</code></td><td>分格模板（存储）</td><td><strong>1</strong></td></tr><tr><td><code>mnalign</code></td><td>对齐预设（存储）</td><td><strong>1</strong></td></tr><tr><td><code>mnlayout</code></td><td>声明式布局（存储）</td><td><strong>1</strong></td></tr><tr><td><code>mnconfig</code></td><td>图库配置（存储）</td><td><strong>1</strong></td></tr><tr><td><code>mnstorage</code></td><td>存储配置（存储）</td><td><strong>1</strong></td></tr></tbody></table><p>版本规则：</p><ul><li>声明版本<strong>高于</strong>应用支持的文件会被拒绝，并给出明确提示：先升级应用。应用绝不猜测未来的格式。</li><li>缺失版本按 <strong>v0</strong> 处理，并在导入时迁移。早期的实验性清单（顶层 <code>images</code>、扁平的 <code>langDirs</code> 映射）会转换为当前结构。</li><li>缺失的可选字段用默认值填充；无效图片会被丢弃，而不是让整个导入失败。</li><li>读取页面 JSON 时会<strong>规范化</strong>：限制矩形范围、移除悬空的分组引用、生成缺失的 id、丢弃未知字段。</li><li>无法解析的页面 JSON 视为不存在；应用会重新检测并重建。</li></ul><h2 id="备份-zip" tabindex="-1">备份 ZIP <a class="header-anchor" href="#备份-zip" aria-label="Permalink to &quot;备份 ZIP&quot;">​</a></h2><p>备份是一个 ZIP，条目以 <code>data/</code> 为前缀：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>data/pages/...</span></span>
<span class="line"><span>data/templates/...</span></span>
<span class="line"><span>data/presets/...</span></span>
<span class="line"><span>data/layouts/...</span></span>
<span class="line"><span>data/library.json</span></span>
<span class="line"><span>data/.backup-meta.json</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>排除：<code>data/cache/</code>（缩略图与远端缓存）、<code>.tmp</code> 文件和日志。恢复会覆盖同名文件，保留备份中没有的页面，并先写入快照。</p><h2 id="尚未实现" tabindex="-1">尚未实现 <a class="header-anchor" href="#尚未实现" aria-label="Permalink to &quot;尚未实现&quot;">​</a></h2><ul><li><strong>词表导出。</strong> PDF 和 Word 分别用导出对话框里的 <strong>PDF（打印）</strong> 和 <strong>Word 文档</strong>。</li><li><strong>定时备份。</strong> 备份和上传到备份目标都需要手动启动。</li><li><strong>应用内的图片转换或批量重命名。</strong> 请在导入前整理文件；见<a href="/KomaYomi-docs/zh/guide/preprocess">预处理与重命名</a>。</li></ul><h2 id="常见坑" tabindex="-1">常见坑 <a class="header-anchor" href="#常见坑" aria-label="Permalink to &quot;常见坑&quot;">​</a></h2><ul><li><strong>引用模式的工程显示缺图。</strong> 清单只存哈希和路径。使用补链目录，或下次用打包模式导出。</li><li><strong>“Schema 版本过新。”</strong> 文件来自更新的版本。请更新应用；不要手工修改 <code>schemaVersion</code>。</li><li><strong>导入覆盖了更新的笔记。</strong> <strong>覆盖</strong> 按设计就是破坏性的。拿不准时用 <strong>合并</strong>；虽然写入了快照，但恢复快照会替换当前数据。</li><li><strong>版式模板没有出现。</strong> 它绑定在当前的话 / 卷筛选上；检查导入对话框中的绑定。</li><li><strong><code>.mnpage.json</code> 导入后没有图片。</strong> 页面数据从不包含图片；图片来自 <code>raw/</code> 或打包工程。</li></ul><figure class="shot"><img src="`+s+'" alt="工程导入摘要：存储方式、清单计数、冲突处理、重新关联目录与“导入”按钮"><figcaption>工程导入摘要：存储方式、清单计数、冲突处理、重新关联目录与“导入”按钮。</figcaption></figure><h2 id="缺失的截图" tabindex="-1">缺失的截图 <a class="header-anchor" href="#缺失的截图" aria-label="Permalink to &quot;缺失的截图&quot;">​</a></h2><table tabindex="0"><thead><tr><th>图</th><th>用于</th></tr></thead><tbody><tr><td>工程导出表单</td><td>模式、名称与备注</td></tr><tr><td>交换文件对话框</td><td>三种文件类型</td></tr></tbody></table><h2 id="相关" tabindex="-1">相关 <a class="header-anchor" href="#相关" aria-label="Permalink to &quot;相关&quot;">​</a></h2><ul><li><a href="/KomaYomi-docs/zh/data-format">数据格式</a> —— 完整的 JSON 字段参考。</li><li><a href="/KomaYomi-docs/zh/guide/export">导出</a> —— HTML、Word、PDF 与 PNG 输出。</li><li><a href="/KomaYomi-docs/zh/guide/remote">远端存储与备份</a> —— 备份目标。</li></ul>',49)])])}const k=n(r,[["render",d]]);export{b as __pageData,k as default};
